            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Das war ein Vorspiel nur, dort wo man Bücher verbrennt, verbrennt man auch am Ende Menschen.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "O weine nicht! Wie glüh’nde Naftatropfen, So fallen deine Thränen auf mein Herz.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Das ist schön bei den Deutschen: Keiner ist so verrückt, dass er nicht einen noch Verrückteren fände, der ihn versteht.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Düfte sind die Gefühle der Blumen.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Die Stadt selbst ist schön, und gefällt einem am besten, wenn man sie mit dem Rücken ansieht.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Rom wollte immer herrschen, und als seine Legionen fielen, sandte es Dogmen in die Provinzen.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Wenn wir es recht überdenken, so stecken wir doch alle nackt in unseren Kleidern.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Vergnügen ist nichts als ein höchst angenehmer Schmerz.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Ja, mich dünkt zuweilen, der Teufel, der Adel und die Jesuiten existieren nur so lange, als man an sie glaubt.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Unser Sommer ist nur ein grün angestrichener Winter, sogar die Sonne muss bei uns eine Jacke von Flanell tragen, wenn sie sich nicht erkälten will.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Geld ist rund und rollt weg, aber Bildung bleibt.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "So ein bisschen Bildung ziert den ganzen Menschen.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "In der Wissenschaft ist alles wichtig.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Wahrlich, es gibt Dinge zwischen Himmel und Erde, die nicht bloß unsere Philosophen, sondern sogar die gewöhnlichsten Dummköpfe nicht begreifen.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Verfolgung der Andersdenkenden ist überall das Monopol der Geistlichkeit.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "An deinen Busen sink ich hin, Und glaube, daß ich selig bin;", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Anfangs wollt ich fast verzagen, Und ich glaubt', ich trüg' es nie, Und ich hab' es doch getragen, - Aber frag mich nur nicht, wie?", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Auf Flügeln des Gesanges, Herzliebchen, trag ich dich fort.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Es ist eine alte Geschichte, Doch bleibt sie immer neu; Und wem sie just passiret, Dem bricht das Herz entzwei.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Ich bin’s gewohnt den Kopf recht hoch zu tragen, Mein Sinn ist auch ein bischen starr und zähe; Wenn selbst der König mir in’s Antlitz sähe, Ich würde nicht die Augen niederschlagen.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Ich glaube, die Wellen verschlingen Am Ende Schiffer und Kahn; Und das hat mit ihrem Singen Die Lore-Ley gethan.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Ich weiß nicht, was soll es bedeuten, Daß ich so traurig bin; Ein Mährchen aus alten Zeiten, Das kommt mir nicht aus dem Sinn.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "St. Denis ist, wie männiglich weiß, der Schutzpatron der Könige von Frankreich, bekanntlich ein Heiliger, der mit seinem eigenen Kopfe in der Hand dargestellt wird.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Der Gedanke geht der Tat voraus wie der Blitz dem Donner. [...] Es wird ein Stück aufgeführt werden in Deutschland, wogegen die französische Revolution nur wie eine harmlose Idylle erscheinen möchte.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Die Fee Morgana, wie würde sie erschrecken, wenn sie etwa einer deutschen Hexe begegnete, die nackt, mit Salben beschmiert, und auf einem Besenstiel, nach dem Brocken reitet.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Von dem Augenblick an, wo eine Religion bei der Philosophie Hülfe begehrt, ist ihr Untergang unabwendlich.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Wir Deutschen hassen gründlich, dauernd; da wir zu ehrlich, auch zu unbeholfen sind, um uns mit schneller Perfidie zu rächen, so hassen wir bis zu unserem letzten Atemzug.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "In der Weltgeschichte ist nicht jedes Ereignis die unmittelbare Folge eines anderen, die Ereignisse bedingen sich vielmehr wechselseitig.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Der lange Schnurrbart ist eigentlich nur Des Zopfthums neuere Phase: Der Zopf, der ehmals hinten hing, Der hängt jetzt unter der Nase.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Der Tisch war gedeckt. Hier fand ich ganz Die altgermanische Küche. Sey mir gegrüßt, mein Sauerkraut, Holdselig sind deine Gerüche!", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Die Göttin hat mir Thee gekocht Und Rum hineingegossen; Sie selber aber hat den Rum Ganz ohne Thee genossen.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Fatal ist mir das Lumpenpack, Das, um die Herzen zu rühren, Den Patriotismus trägt zur Schau Mit allen seinen Geschwüren.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Ich möchte nicht todt und begraben seyn Als Kaiser zu Aachen im Dome; Weit lieber lebt’ ich als kleinster Poet Zu Stukkert am Neckarstrome.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Sie stelzen noch immer so steif herum, So kerzengrade geschniegelt, Als hätten sie verschluckt den Stock Womit man sie einst geprügelt.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Zu Aachen langweilen sich auf der Straß’ Die Hunde, sie flehn unterthänig: Gieb uns einen Fußtritt, o Fremdling, das wird Vielleicht uns zerstreuen ein wenig.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Der Historiker ist immer ein Merlin, er ist die Stimme einer begrabenen Zeit, man befragt ihn, und er gibt Antwort, der rückwärtsschauende Prophet.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Ich las das langweilige Buch, schlief darüber ein, im Schlafe träumte ich, weiter zu lesen, erwachte vor Langeweile, und das dreimal.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Ärgert dich dein Auge, so reiß es aus, ärgert dich deine Hand, so hau sie ab, ärgert dich deine Zunge, so schneide sie ab, und ärgert dich deine Vernunft, so werde katholisch.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Altdeutschland, wir weben dein Leichentuch, wir weben hinein den dreyfachen Fluch, wir weben, wir weben.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Armut ist das Los der großen Menschheitshelfer", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Denk ich an Deutschland in der Nacht, dann bin ich um den Schlaf gebracht.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Die Handlungen eines Furchtigen, wie die eines Genies, liegen außerhalb aller Berechnungen.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Die Religion kann nie schlimmer sinken, als wenn sie solchermaßen zur Staatsreligion erhoben wird.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Die Verleumdung, das freche Gespenst, setzt sich auf die edelsten Gräber.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Er sprach mit jener stillen, impertinenten Zurückhaltung, die noch unerträglicher ist als die vollauteste Aufschneiderei.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Es gibt zwei Sorten Ratten: Die hungrigen und satten.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Ich habe immer unter Jüdinnen die gesündesten Naturen gefunden, und ich kann es Gott Vater gar nicht verdenken, dass er der bethlehemitischen Maria die Cour und ein Kind gemacht.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Ich weiß nicht, was soll es bedeuten, Daß ich so traurig bin; Ein Märchen aus alten Zeiten, Das kommt mir nicht aus dem Sinn.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Ihr könnt Euch darauf verlassen, die Bescheidenheit der Leute hat immer ihre guten Gründe.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "In meinem Hirne rumort es und knackt, Ich glaube, da wird ein Koffer gepackt, Und mein Verstand reist ab - o wehe! - noch früher als ich selber gehe.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "In uns selbst liegen die Sterne unseres Glücks.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Leise zieht durch mein Gemüt liebliches Geläute.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Schlage die Trommel und fürchte dich nicht, und küsse die Marketenderin! Das ist die ganze Wissenschaft, das ist der Bücher tiefster Sinn.", Author = "Heinrich Heine" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Heinrich_Heine", Text = "Wenn es den Kaiser juckt, so müssen die Völker sich kratzen.", Author = "Heinrich Heine" },
